+    #[test]
+    fn point_leaf_index_matches_reference_and_validates_before_accept() {
+        fn compare(payload: &[u8], low: &[u8], high: &[u8], reject: bool) {
+            let mut results = Vec::new();
+            for old in [true, false] {
+                let _scope = old.then(point_leaf_index_reference::Scope::start);
+                let mut calls = Vec::new();
+                let step = PointStep::borrowed(payload, low, high, &mut |key| {
+                    calls.push(key.to_vec());
+                    !reject || key.last().is_some_and(|b| b % 3 == 0)
+                }).map_err(|e| e.kind());
+                if step.is_err() { assert!(calls.is_empty(), "invalid tail reached accept"); }
+                results.push((step, calls));
+            }
+            assert_eq!(results[0], results[1]);
+        }
+        let keys = vec![vec![], vec![0], vec![0, 0], vec![0, 255], vec![1], vec![255; 257]];
+        let entries: Vec<_> = keys.iter().enumerate().map(|(i, k)|
+            (k.clone(), RowId(if i % 3 == 0 { None } else { Some(vec![i as u8; i * 7]) }))).collect();
+        for next_leaf in [None, Some(PageId(42))] {
+            for entries in [Vec::new(), entries.clone()] {
+                let payload = bincode::serialize(&BTreeNode::Leaf { entries, next_leaf }).unwrap();
+                for low in &keys {
+                    for high in &keys { for reject in [false, true] { compare(&payload, low, high, reject); } }
+                }
+                // Truncation at every byte, malformed lengths/tags/order/tails,
+                // and zero padding must agree with the pre-change decoder.
+                for end in 0..payload.len() { compare(&payload[..end], &[], &[255; 300], false); }
+                for at in 0..payload.len() {
+                    for value in [0, 1, 255] {
+                        let mut bad = payload.clone(); bad[at] = value;
+                        compare(&bad, &[], &[255; 300], false);
+                    }
+                }
+                let mut padded = payload; padded.resize(MAX_PAYLOAD, 0);
+                compare(&padded, &[], &[255; 300], false);
+                *padded.last_mut().unwrap() = 1;
+                compare(&padded, &[], &[255; 300], false);
+            }
+        }
+        for bad in [
+            BTreeNode::Leaf { entries: vec![(vec![1], RowId(None)), (vec![1], RowId(None))], next_leaf: None },
+            BTreeNode::Leaf { entries: vec![(vec![2], RowId(None)), (vec![1], RowId(None))], next_leaf: None },
+            BTreeNode::Internal { keys: vec![], children: vec![PageId(1)] },
+        ] { compare(&bincode::serialize(&bad).unwrap(), &[], &[255], false); }
+        // Independently check the index and accepted row, so two decoders
+        // agreeing on an accidentally shared error cannot pass this guard.
+        let payload = bincode::serialize(&BTreeNode::Leaf { entries: entries.clone(), next_leaf: None }).unwrap();
+        let mut offsets = Vec::new();
+        let MaintenanceNode::Leaf { rows, count, .. } = MaintenanceNode::decode_recording(&payload,
+            |index, offset| { assert_eq!(index, offsets.len()); offsets.push(offset); Ok(()) }).unwrap() else { panic!() };
+        assert_eq!(count, entries.len());
+        assert_eq!(offsets.len(), count);
+        for ((key, value), at) in entries.iter().zip(offsets) {
+            assert_eq!(NodeBytes(&rows[at..]).row().unwrap(), (key.as_slice(), value.0.as_deref()));
+            assert_eq!(PointStep::borrowed(&payload, key, key, &mut |_| true).unwrap(),
+                PointStep::Hit(key.clone(), value.clone()));
+        }
+    }
